import React from 'react';
import NavBar from '../Components/NavBar';

const MoreDesigns = () => {
  return (
    <>
    <NavBar/>
      <h1 style={{ textAlign: 'center', margin: '40px 0', fontSize: '2.5rem', color: '#3c2c2b' }}>
        Pattern Ideas
      </h1>

      <div style={{ display: 'flex', gap: '24px', justifyContent: 'center', flexWrap: 'wrap', padding: '0 20px' }}>
        {/* Pinterest Board Embed 1 */}
        <div
          style={{ width: '45%', minWidth: '320px', maxWidth: '600px', height: '520px', overflow: 'auto', borderRadius: '12px', boxShadow: '0 4px 16px rgba(44,44,44,0.15)' }}
          dangerouslySetInnerHTML={{
            __html: `
            <a data-pin-do="embedBoard" data-pin-board-width="400" data-pin-scale-height="420" data-pin-scale-width="80" href="https://www.pinterest.com/aromifashionacademy/fashion-dresses/"></a>
            <script async defer src="https://assets.pinterest.com/js/pinit.js"></script>`,
          }}
        />

        {/* Pinterest Board Embed 2 */}
        <div
          style={{ width: '45%', minWidth: '320px', maxWidth: '600px', height: '520px', overflow: 'auto', borderRadius: '12px', boxShadow: '0 4px 16px rgba(44,44,44,0.15)' }}
          dangerouslySetInnerHTML={{
            __html: `
            <a data-pin-do="embedBoard" data-pin-board-width="400" data-pin-scale-height="420" data-pin-scale-width="80" href="https://www.pinterest.com/aromifashionacademy/ruffle-hem-dress/"></a>
            <script async defer src="https://assets.pinterest.com/js/pinit.js"></script>`,
          }}
        />
      </div>
    </>
  );
};

export default MoreDesigns;
